using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;

namespace Kisib
{
    // Color emoji for the few kisib uses: Windows' GDI text only draws emoji in black and white, so these are
    // drawn as small pictures instead. Images: Microsoft Fluent Emoji (3D), MIT License, Copyright (c) Microsoft
    // Corporation (docs/third-party-notices.txt), shrunk to 64 px.
    internal static class EmojiImages
    {
        private static readonly Dictionary<int, string> Png = new Dictionary<int, string>
        {
            { 0x1F50C, "" },
            { 0x1F33F, "" },
            { 0x1F3DB, "" },
            { 0x1F451, "" },
            { 0x1F483, "" },
            { 0x1F511, "" },
            { 0x1F6AB, "" },
            { 0x1F921, "" },
            { 0x1F9F1, "" },
            { 0x26D4, "" },
            { 0x2754, "" },
        };
        private static readonly Dictionary<int, Image> cache = new Dictionary<int, Image>();

        internal static Image For(int codePoint)
        {
            lock (cache)
            {
                Image image;
                if (cache.TryGetValue(codePoint, out image)) return image;
                string b64;
                image = null;
                if (Png.TryGetValue(codePoint, out b64))
                    try { image = new Bitmap(new MemoryStream(Convert.FromBase64String(b64))); } catch (Exception) { image = null; }
                cache[codePoint] = image;
                return image;
            }
        }
    }
}
